{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "Inclusion criteria were as follows: (i) randomised controlled trials (RCTs), (ii) studies comparing 3D printing-assisted surgery to conventional surgery, (iii) treatment of fractures of the foot and/or ankle, (iv) published in 2012 or later, (v) outcome measures include at least 2 of: intraoperative blood loss, operation duration and fluoroscopy time.",
      "reason": "The evidence specifies eligible study design (RCTs), comparison (3D printing-assisted vs conventional), participants/condition (foot/ankle fractures), and required outcome measures. However, it does not clearly specify follow-up requirements or relevant setting information at the eligibility-criteria level."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The following exclusion criteria were applied: (i) any other study type, (ii) non-English language, (iii) non-human studies, (iv) cadaveric studies, (v) studies investigating primarily patients with pathologies other than trauma (e.g. tumours, osteoporosis), (vi) studies published before 2012.",
      "reason": "Report characteristics for eligibility are specified, including language (non-English excluded) and publication year (published in 2012 or later; those before 2012 excluded). Publication/report status beyond these aspects is not mentioned in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was retrieved describing how exclusions were differentiated based on whether outcomes were not measured versus not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "A metaanalysis of a subgroup of studies that reported quantitative data for the outcomes: operation duration, intraoperative blood loss, number of times fluoroscopy was used, and American Orthopaedic Foot and Ankle Society (AOFAS) Ankle-Hindfoot Rating System scores in control and 3D printing intervention groups were conducted in RevMan 5.3",
      "reason": "The synthesis groups are explicitly described as 'control' and '3D printing intervention groups', corresponding to the study comparison (3D printing-assisted surgery vs conventional)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence lists inclusion/exclusion criteria but does not provide rationales for notable restrictions on study eligibility."
    }
  ],
  "confidence": 78
}

